  refreshControl={
    <RefreshControl
      onRefresh={() => refetchCalendar()}
      refreshing={isRefetchingCalendar}
    />
  }
  data={ungroupedAndSortedCalendar}
  keyExtractor={(item) => {
    return item.startDate;
  }}
  estimatedItemSize={700}
